// ============================================================================
// ACE_Lite_apb: APB4 register wrapper around ACE_Lite_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ACE_Lite.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ACE_Lite.md
// ============================================================================
module ACE_Lite_apb #(
  parameter int DW = 32,
  parameter int AW = 32
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic awvalid,
  output logic awready,
  input logic [AW-1:0] awaddr,
  input logic [7:0] awlen,
  input logic [2:0] awsize,
  input logic [1:0] awburst,
  input logic [2:0] awsnoop,
  input logic [1:0] awdomain,
  input logic [1:0] awbar,
  input logic wvalid,
  output logic wready,
  input logic [DW-1:0] wdata,
  input logic [DW/8-1:0] wstrb,
  input logic wlast,
  output logic bvalid,
  input logic bready,
  output logic [1:0] bresp,
  input logic arvalid,
  output logic arready,
  input logic [AW-1:0] araddr,
  input logic [7:0] arlen,
  input logic [2:0] arsize,
  input logic [1:0] arburst,
  input logic [3:0] arsnoop,
  input logic [1:0] ardomain,
  input logic [1:0] arbar,
  output logic rvalid,
  input logic rready,
  output logic [DW-1:0] rdata,
  output logic [1:0] rresp,
  output logic rlast
);
  localparam logic [31:0] ID_VALUE = 32'h41450200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  ACE_Lite_top #(.DW(DW), .AW(AW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .awvalid(awvalid),
    .awready(awready),
    .awaddr(awaddr),
    .awlen(awlen),
    .awsize(awsize),
    .awburst(awburst),
    .awsnoop(awsnoop),
    .awdomain(awdomain),
    .awbar(awbar),
    .wvalid(wvalid),
    .wready(wready),
    .wdata(wdata),
    .wstrb(wstrb),
    .wlast(wlast),
    .bvalid(bvalid),
    .bready(bready),
    .bresp(bresp),
    .arvalid(arvalid),
    .arready(arready),
    .araddr(araddr),
    .arlen(arlen),
    .arsize(arsize),
    .arburst(arburst),
    .arsnoop(arsnoop),
    .ardomain(ardomain),
    .arbar(arbar),
    .rvalid(rvalid),
    .rready(rready),
    .rdata(rdata),
    .rresp(rresp),
    .rlast(rlast),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
